class Solution {
public:
    string answerString(string word, int numFriends) {
        if (numFriends == 1) return word;
        int n = word.length();
        int maxLen = n - numFriends + 1;
        string best = "";
        for (int i = 0; i < n; ++i) {
            string sub = word.substr(i, min((int)word.length() - i, maxLen));
            if (sub > best) {
                best = sub;
            }
        }
        return best;
    }
};

class Solution {
    public String answerString(String word, int numFriends) {
        if (numFriends == 1) return word;
        int n = word.length();
        int maxLen = n - numFriends + 1;
        String best = "";
        for (int i = 0; i < n; ++i) {
            String sub = word.substring(i, Math.min(n, i + maxLen));
            if (sub.compareTo(best) > 0) {
                best = sub;
            }
        }
        return best;
    }
}

var answerString = function(word, numFriends) {
    if (numFriends === 1) return word;
    const n = word.length;
    const maxLen = n - numFriends + 1;
    let best = "";
    for (let i = 0; i < n; ++i) {
        const sub = word.slice(i, i + maxLen);
        if (sub > best) {
            best = sub;
        }
    }
    return best;
};
